contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        // Precondition: no specific input; the contract may hold balance before the call.
        require(true);

        uint balBefore = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // withdrawAll must not revert for the owner (the test contract deployed c, so it is the owner)
        // and must transfer the entire balance of c to the owner (this contract).
        assert(!reverted && address(c).balance == 0 && address(this).balance >= balBefore);
    }

    receive() external payable {}
}

