contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount <= address(this).balance);

        // Fund c through its payable fallback so withdrawAll has something to withdraw.
        if (amount > 0) {
            c.f{value: amount}();
        }

        uint balBefore = address(c).balance;
        uint thisBefore = address(this).balance;
        uint depositsBefore = c.depositsCount();

        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        if (reverted) {
            assert(c.depositsCount() == depositsBefore);
            assert(address(c).balance == balBefore);
        } else {
            assert(address(c).balance == 0);
            assert(address(this).balance == thisBefore + balBefore);
            assert(c.owner() != address(this));
        }
    }

    receive() external payable {}
}

