        uint cBalBefore = address(c).balance;
        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint cBalAfter = address(c).balance;

        assert((reverted && cBalAfter == cBalBefore) || (!reverted && cBalBefore >= value && cBalAfter == cBalBefore - value));
    }

    receive() external payable {}
}
